const CACHE='filscash-v3';
const SHELL='/__shell__';
const OFFLINE_IMG="data:image/webp;base64,";

// نسخة نظيفة (بدون redirect) حتى لا يعطي المتصفح ERR_FAILED
async function clean(r){
  const b=await r.blob();
  return new Response(b,{status:r.status,statusText:r.statusText,headers:r.headers});
}
function offlinePage(){
  const html='<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8">'+
  '<meta name="viewport" content="width=device-width,initial-scale=1"><title>Fils Cash</title>'+
  '<style>html,body{margin:0;height:100%;background:linear-gradient(to bottom,#040b1d 0%,#050b1c 8%,#050c1d 17%,#050c1c 25%,#030c1b 33%,#020b1b 42%,#03081a 50%,#030818 58%,#030818 67%,#030817 75%,#020816 83%,#02040e 92%,#000107 100%)}img{width:100%;height:100vh;object-fit:contain;display:block}</style></head>'+
  '<body><img src="'+OFFLINE_IMG+'" alt="">'+
  '<script>setInterval(function(){fetch(location.pathname+"?ping="+Date.now(),{method:"HEAD",cache:"no-store"}).then(function(){location.reload()}).catch(function(){})},3000);'+
  'addEventListener("online",function(){location.reload()});<\/script></body></html>';
  return new Response(html,{status:200,headers:{'Content-Type':'text/html; charset=utf-8'}});
}

self.addEventListener('install',e=>{
  e.waitUntil(
    fetch('/',{cache:'reload'}).then(clean).then(r=>caches.open(CACHE).then(c=>c.put(SHELL,r))).catch(()=>{})
  );
  self.skipWaiting();
});
self.addEventListener('activate',e=>{
  e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==CACHE).map(x=>caches.delete(x)))));
  self.clients.claim();
});
self.addEventListener('fetch',e=>{
  if(e.request.mode!=='navigate')return;
  e.respondWith(
    fetch(e.request).then(async r=>{
      if(r.ok){const c=await clean(r.clone());(await caches.open(CACHE)).put(SHELL,c);}
      return r;
    }).catch(async()=>{
      const cached=await caches.match(SHELL);
      return cached||offlinePage();
    })
  );
});
